<?php
declare(strict_types=1); require_once __DIR__.'/includes/auth.php'; require_once __DIR__.'/includes/csrf.php'; require_once __DIR__.'/connection.php'; require_alumni();$email=$_SESSION['user_email'];$message='';$type='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$school=trim($_POST['school_or_issuer']??'');$title=trim($_POST['title']??'');$kind=$_POST['record_type']??'Education';if($school===''||$title===''){$message='Institution and title are required.';$type='danger';}else{$stmt=mysqli_prepare($connection,'INSERT INTO education_certifications(email,record_type,school_or_issuer,title,field_of_study,year_completed,description) VALUES(?,?,?,?,?,?,?)');$field=trim($_POST['field_of_study']??'');$year=trim($_POST['year_completed']??'');$desc=trim($_POST['description']??'');if($stmt){mysqli_stmt_bind_param($stmt,'sssssss',$email,$kind,$school,$title,$field,$year,$desc);mysqli_stmt_execute($stmt);mysqli_stmt_close($stmt);$message='Record saved successfully.';$type='success';}}}$records=[];$stmt=mysqli_prepare($connection,'SELECT * FROM education_certifications WHERE email=? ORDER BY year_completed DESC,id DESC');if($stmt){mysqli_stmt_bind_param($stmt,'s',$email);mysqli_stmt_execute($stmt);$r=mysqli_stmt_get_result($stmt);while($row=mysqli_fetch_assoc($r))$records[]=$row;mysqli_stmt_close($stmt);}$pageTitle='Education & Certifications';?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Education | AlumTrace</title><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css"><link rel="stylesheet" href="assets/css/alumtrace.css"></head><body><?php require __DIR__.'/includes/sidebar.php';?><div class="main-wrapper"><?php require __DIR__.'/includes/topbar.php';?><main class="content"><div class="page-head"><h2>Education & Certifications</h2><p>Collect your academic achievements and professional credentials.</p></div><?php if($message):?><div class="alert alert-<?=$type?>"><?=htmlspecialchars($message)?></div><?php endif;?><div class="panel"><form method="post"><?=csrf_field()?><div class="fields cols-2"><div class="field"><label>Record type</label><select class="select" name="record_type"><option>Education</option><option>Certification</option></select></div><div class="field"><label>Institution / issuer</label><input class="input" name="school_or_issuer" required></div><div class="field"><label>Degree / title</label><input class="input" name="title" required></div><div class="field"><label>Field of study</label><input class="input" name="field_of_study"></div><div class="field"><label>Year completed</label><input class="input" name="year_completed" maxlength="4"></div></div><div class="field"><label>Description</label><textarea class="textarea" name="description"></textarea></div><button class="btn btn-primary" type="submit">Add record</button></form></div><div class="panel" style="margin-top:22px"><h2>My records</h2><div class="record-list"><?php foreach($records as $record):?><article class="record-card"><span class="tag"><?=htmlspecialchars($record['record_type'])?></span><h3><?=htmlspecialchars($record['title'])?></h3><p><?=htmlspecialchars($record['school_or_issuer'])?> · <?=htmlspecialchars($record['year_completed']?:'Year not provided')?></p><p class="muted"><?=nl2br(htmlspecialchars($record['description']??''))?></p></article><?php endforeach;if(!$records):?><p class="muted">No education records yet.</p><?php endif;?></div></div></main><?php require __DIR__.'/includes/dashboard-footer.php';?></div><script src="assets/js/alumtrace.js"></script></body></html>
